diff --git a/repro/check.js b/repro/check.js
new file mode 100644
index 000000000..50f957d8f
--- /dev/null
+++ b/repro/check.js
@@ -0,0 +1,28 @@
+// Run from the repo root: node repro/check.js
+// Prints the type that the checker displays for `Test` in repro/issue.ts and
+// exits 1 when it is the 5.7 (wrong) display `{ prop1: Wrapper<"hello">; }`.
+const path = require("path");
+const ts = require(path.resolve(process.env.TS_LIB || "built/local/typescript.js"));
+
+const file = path.resolve(__dirname, "issue.ts");
+const program = ts.createProgram([file], { strict: true, noEmit: true, target: ts.ScriptTarget.ESNext, types: [] });
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+
+let testAlias;
+ts.forEachChild(sf, n => { if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") testAlias = n; });
+const type = checker.getTypeAtLocation(testAlias.name);
+
+const shown = checker.typeToString(type, undefined, ts.TypeFormatFlags.InTypeAlias | ts.TypeFormatFlags.NoTruncation);
+const prop = type.getProperty("prop1");
+const propActual = checker.typeToString(checker.getTypeOfSymbolAtLocation(prop, testAlias));
+
+console.log(`typescript ${ts.version}`);
+console.log(`Test (displayed)        = ${shown}`);
+console.log(`Test["prop1"] (actual)  = ${propActual}`);
+
+if (shown.includes('Wrapper<"hello">')) {
+    console.log('BUG PRESENT: expected `{ prop1: "hello"; }`');
+    process.exit(1);
+}
+console.log("OK");
diff --git a/repro/issue.ts b/repro/issue.ts
new file mode 100644
index 000000000..0f1c6e96e
--- /dev/null
+++ b/repro/issue.ts
@@ -0,0 +1,22 @@
+// Reporter's code, verbatim.
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
